KlpApplication.code:
final scope = KlpId.root('example');
final destination = KlpDestination<Object?, Object?>(scope / 'home');
final router = KlpRouter(
	id: scope / 'router',
	initial: destination.location(null),
	routes: [
		KlpRoute<Object?, Object?>(destination, screen: (input) => screen),
	],
);
final application = KlpApplication(
	title: 'Example',
	primitives: KlpWorkspacePreset.light(),
	router: router,
);
runKlpApp(KlpMutableState(application).readOnly);

KlpScreen.code:
final screen = KlpScreen(
	id: scope / 'screen',
	accessibilityLabel: 'Example screen',
	child: layout,
);

KlpAdaptive.code:
final adaptive = KlpAdaptive(
	id: scope / 'adaptive',
	fallback: layout,
	strategies: const {},
);

KlpAppLayout.code:
final layout = KlpAppLayout(
	id: scope / 'layout',
	child: KlpAppFrame(
		id: scope / 'frame',
		child: groups,
	),
);
